oracle:
def dedupe_keep(xs):
    seen, out = set(), []
    for x in xs:
        k = x.strip().lower()
        if k in seen:
            continue
        seen.add(k)
        out.append(x)
    return out

partial:
def dedupe_keep(xs):
    out = []
    for x in xs:
        if x not in out:
            out.append(x)
    return out

